SELECT id, subject_table, subject_id, field_path, claim_text, source_id, citation, note, status FROM jsonb_populate_recordset(NULL::public.fact_claim, '[{"subject_table": "event", "field_path": "description", "claim_text": "董璋致在洛阳的宫苑使董光业书，称朝廷削地屯兵欲杀己，若再发兵入斜谷则必反。", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p030·原文件第35行", "note": "原文：董璋之子光业为宫苑使，在洛阳，璋与书曰：“朝廷割吾支郡为节镇，屯兵三千，是杀我必矣。汝见枢要为吾言：如朝廷更发一骑入斜谷，吾必反！与汝诀矣。”；核对说明：三千驻兵和欲杀为董书说法，一骑为假设触发条件，非本句已发一骑；与汝诀是决绝书语非儿子已死。", "status": "draft", "id": "9541e9df-17a6-5eb5-8880-10f65373bbc7", "subject_id": "423258c1-5f46-5270-a48b-2fb18be7348c", "source_id": "27cb9b1c-b88a-5003-ae94-8389135c5745"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "930年本段；主句未独纪月日", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p030·原文件第35行", "note": "原文：董璋之子光业为宫苑使，在洛阳，璋与书曰：“朝廷割吾支郡为节镇，屯兵三千，是杀我必矣。汝见枢要为吾言：如朝廷更发一骑入斜谷，吾必反！与汝诀矣。”；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "88832297-bd87-55ab-b4d5-d91476b5e7e4", "subject_id": "423258c1-5f46-5270-a48b-2fb18be7348c", "source_id": "27cb9b1c-b88a-5003-ae94-8389135c5745"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记董璋：致书、以再发兵为反叛条件者。", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p030·原文件第35行", "note": "原文：董璋之子光业为宫苑使，在洛阳，璋与书曰：“朝廷割吾支郡为节镇，屯兵三千，是杀我必矣。汝见枢要为吾言：如朝廷更发一骑入斜谷，吾必反！与汝诀矣。”；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "2a6de95a-356b-5766-bfe6-0916176a9293", "subject_id": "ecbba4d7-b26a-5c43-ad24-180221fafb2b", "source_id": "27cb9b1c-b88a-5003-ae94-8389135c5745"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "董璋：致书、以再发兵为反叛条件者。", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p030·原文件第35行", "note": "原文：董璋之子光业为宫苑使，在洛阳，璋与书曰：“朝廷割吾支郡为节镇，屯兵三千，是杀我必矣。汝见枢要为吾言：如朝廷更发一骑入斜谷，吾必反！与汝诀矣。”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "6a54efb3-5330-57bb-a919-f41f39636dbc", "subject_id": "014a93e0-4857-5450-b1f6-23da62c89504", "source_id": "27cb9b1c-b88a-5003-ae94-8389135c5745"}, {"subject_table": "person", "field