: "1c4b4b1d-8fe1-5d86-89f8-d9d0f00cd94c", "subject_id": "ef061cac-1ddb-5d2d-8961-989619416470", "source_id": "27cb9b1c-b88a-5003-ae94-8389135c5745"}, {"subject_table": "person", "field_path": "description", "claim_text": "主记安重诲久专大权，中外恶之者众。", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p032·原文件第37行", "note": "原文：安重诲久专大权，中外恶之者众；；核对说明：这是主书对当时权势与反感的概括，无名单人数，不作民意统计或起年。", "status": "draft", "id": "8cbec714-b684-5070-9b33-98c10b065f6d", "subject_id": "ce1aed16-1e3c-550a-954b-f37ff4743d0c", "source_id": "27cb9b1c-b88a-5003-ae94-8389135c5745"}, {"subject_table": "event", "field_path": "description", "claim_text": "安重诲因忧惧上表请解机务，李嗣源表示无嫌并提诬告者已诛。", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p032·原文件第37行", "note": "原文：重诲内忧惧，表解机务，上曰：“朕无间于卿，诬罔者朕既诛之矣，卿何为尔？”；核对说明：表解为请辞未获准；帝称诬者已诛承前案，不再造一次斩告者。", "status": "draft", "id": "6bddc763-72f3-5575-b606-31136441af25", "subject_id": "c0d5bb7e-80b8-5112-8228-651fe5fab190", "source_id": "27cb9b1c-b88a-5003-ae94-8389135c5745"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "930年九月甲戌面奏前", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p032·原文件第37行", "note": "原文：重诲内忧惧，表解机务，上曰：“朕无间于卿，诬罔者朕既诛之矣，卿何为尔？”；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "79a3f280-400a-534d-8c54-3bfeaf0d16eb", "subject_id": "c0d5bb7e-80b8-5112-8228-651fe5fab190", "source_id": "27cb9b1c-b88a-5003-ae94-8389135c5745"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "安重诲：上表请解机务者。", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p032·原文件第37行", "note": "原文：重诲内忧惧，表解机务，上曰：“朕无间于卿，诬罔者朕既诛之矣，卿何为尔？”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "f46ee461-0cdd-5644-90eb-340b387a39b5", "subject_id": "0a1b0f79-9781-5999-ac79-320802bf2f99", "source_id": "27cb9b1c-b88a-5003-ae94-8389135c5745"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李嗣源：拒其忧疑、慰言者。", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p032·原文件第37行", "note": "原文：重诲内忧惧，表解机务，上曰：“朕无间于卿，诬罔者朕既诛之矣，卿何为尔？”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "af7b1959-606a-56d1-bcc8-5559842a19d0", "subject_id": "aa61d54b-c58f-558b-b9a6-e3e9ad9b6489", "source_id": "27cb9b1c-b88a-5003-ae94-8389135c5745"}, {"subject_table": "event", "field_path": "description", "claim_text": "安重诲面奏屡请一镇以全余生，李嗣源先拒后怒称听去。", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p032·原文件第37行", "note": "原文：甲戌，重诲复面奏曰：“臣以寒贱，致位至此，忽为人诬以反，非陛下至明，臣无种矣。由臣才薄任重，恐终不能镇浮言，愿赐一镇以全馀生。”上不许；重诲求之不已，上怒曰：“听卿去，朕不患无人！”；核对说明：臣无种是假设若无帝明将灭族，不当安族已经尽死；听去是怒言，主之后安如故，不能写成当日已罢枢密使赴镇。", "status": "draft", "id": "0e67e9f9-ab28-5c45-bf70-1294476cae52", "subject_id": "819423b0-ef1d-5402-a91c-4bfa5f4a5b7c", "source_id": "27cb9b1c-b88a-5003-ae94-8389135c5745"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "930年九月甲戌", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p032·原文件第37行", "note": "原文：甲戌，重诲复面奏曰：“臣以寒贱，致位至此，忽为人诬以反，非陛下至明，臣无种矣。由臣才薄任重，恐终不能镇浮言，愿赐一镇以全馀生。”上不许；重诲求之不已，上怒曰：“听卿去，朕不患无人！”；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "cf06e271-47ae-5f72-ac70-5e07f4970513", "subject_id": "819423b0-ef1d-5402-a91c-4bfa5f4a5b7c", "source_id": "27cb9b1c-b88a-5003-ae94-8389135c5745"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "安重诲：面奏屡请出镇者。", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p032·原文件第37行", "note": "原文：甲戌，重诲复面奏曰：“臣以寒贱，致位至此，忽为人诬以反，非陛下至明，臣无种矣。由臣才薄任重，恐终不能镇浮言，愿赐一镇以全馀生。”上不许；重诲求之不已，上怒曰：“听卿去，朕不患无人！”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "8ee7e21c-77d4-5c53-9004-2a7046b619d0", "subject_id": "94c966cd-d4cf-576b-b208-1acf0bf245dd", "source_id": "27cb9b1c-b88a-5003-ae94-8389135c5745"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李嗣源：先拒后怒言听去者。", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p032·原文件第37行", "note": "原文：甲戌，重诲复面奏曰：“臣以寒贱，致位至此，忽为人诬以反，非陛下至明，臣无种矣。由臣才薄任重，恐终不能镇浮言，愿赐一镇以全馀生。”上不许；重诲求之不已，上怒曰：“听卿去，朕不患无人！”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "79e3303d-585c-587e-b4ce-3ffe26fae387", "subject_id": "b132cf37-dac0-5a1e-8629-e535d34de6de", "source_id": "27cb9b1c-b88a-5003-ae94-8389135c5745"}, {"subject_table": "event", "field_path": "description", "claim_text": "范延光劝留安重诲，李嗣源询其可否代任，范以资浅才不及辞。", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p032·原文件第37行", "note": "原文：前成德节度使范延光劝上留重诲，且曰：“重诲去，谁能代之？”上曰：“卿岂不可？”延光曰：“臣受驱策日浅，且才不逮重诲，何敢当此？”；核对说明：辞代为本次应对，不否定后甲申实受任；前成德主衔、旧在镇州同军职称法，无需新同名人物。", "status": "draft", "id": "8fd101f5-597c-5d90-8681-20088b40b03e", "subject_id": "4b2cb7dd-b501-59b6-a366-0c980e335b88", "source_id": "27cb9b1c-b88a-5003-ae94-8389135c5745"}, {"subject_table": "event", "field_path": "time_original", "claim_text": "930年九月甲戌请辞时", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p032·原文件第37行", "note": "原文：前成德节度使范延光劝上留重诲，且曰：“重诲去，谁能代之？”上曰：“卿岂不可？”延光曰：“臣受驱策日浅，且才不逮重诲，何敢当此？”；核对说明：按主书及对应补证纪时；追叙或他书记载另作说明，不自行换算公历日期。", "status": "draft", "id": "957dda5e-8682-5696-93ab-f237b06134fd", "subject_id": "4b2cb7dd-b501-59b6-a366-0c980e335b88", "source_id": "27cb9b1c-b88a-5003-ae94-8389135c5745"}, {"subject_table": "person", "field_path": "description", "claim_text": "本段记范延光：前成德节度使、劝留并辞代者。", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p032·原文件第37行", "note": "原文：前成德节度使范延光劝上留重诲，且曰：“重诲去，谁能代之？”上曰：“卿岂不可？”延光曰：“臣受驱策日浅，且才不逮重诲，何敢当此？”；核对说明：核对同名、职务及行动后识别主体；展示简体，摘录保留原字。", "status": "draft", "id": "86238784-42ac-504d-8970-a8183bad3742", "subject_id": "6889e460-4b23-5243-9441-b5c3a78da98f", "source_id": "27cb9b1c-b88a-5003-ae94-8389135c5745"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "范延光：前成德节度使、劝留并辞代者。", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p032·原文件第37行", "note": "原文：前成德节度使范延光劝上留重诲，且曰：“重诲去，谁能代之？”上曰：“卿岂不可？”延光曰：“臣受驱策日浅，且才不逮重诲，何敢当此？”；核对说明：参与身份依据本句；人名沿用已有主体，原文不改字。", "status": "draft", "id": "c00872a1-fe89-55c4-b310-3356d054c9b3", "subject_id": "e36cd97f-5da6-5d95-b9e9-c3d30b989b3c", "source_id": "27cb9b1c-b88a-5003-ae94-8389135c5745"}, {"subject_table": "person_event", "field_path": "role", "claim_text": "李嗣源：询范能否代者。", "citation": "卷277·长兴元年（930）·zztj-v277-y0930-p032·原文件第37行", "note": "原文：前成德节度使范延光劝上留重诲，且曰：“重诲去，谁能代之？”上曰：“卿岂不可？”延